import{t as e}from"./utils-COoNfFoj.js";var t={slug:`joana-rocha`,influencerName:`Joana Rocha`,influencerHandle:`@JoanaRocha`,influencerAvatarUrl:`${e}/joana-rocha-avatar.jpeg`,heroDescription:`One of the biggest challenges of people looking for jobs is knowing how to prepare well for interviews — so I built an interview prep center that has everything you need to be able to prepare in less than 1 hour: from company information to expected questions per stage and also an interview prep space.`,assetTitle:`Career Coach`,screenshotUrl:`${e}/joana-rocha.png`,remixUrl:`https://www.perplexity.ai/computer/a/techtalk-career-coach-qdQkjyjVQImymBTULUzU7A`,promptTitle:`Try Joana's prompt`,promptText:`Build a single-user career coaching web app called TechTalk Career Coach. It’s a four-section dashboard that takes a pre-loaded CV, asks 5 onboarding questions, then gives an honest match-rate against the target role plus a week-by-week plan to close the gap. Use a Vite + React + Tailwind + Express + SQLite fullstack template. Default profile is pre-loaded — never ask the user to upload a CV. British English everywhere. No emojis except a single ☕ in the morning brief greeting.`};export{t as default};
